<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>COVID-19 Emergency Response: From Detection to Recovery - Infographic</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body {
    width: 2384px;
    height: 3370px;
    overflow: hidden;
    font-family: 'Inter', 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
    background: #f8fafc;
  }
  .poster {
    width: 2384px;
    height: 3370px;
    display: flex;
    flex-direction: column;
    background: linear-gradient(180deg, #f0f7ff 0%, #ffffff 15%, #ffffff 85%, #f0f7ff 100%);
    position: relative;
    overflow: hidden;
  }

  /* Decorative background elements */
  .poster::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 12px;
    background: linear-gradient(90deg, #0077C0, #00A5D9, #0077C0);
  }
  .poster::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 12px;
    background: linear-gradient(90deg, #0077C0, #00A5D9, #0077C0);
  }

  .bg-circle {
    position: absolute;
    border-radius: 50%;
    opacity: 0.04;
    background: #0077C0;
  }
  .bg-circle-1 { width: 800px; height: 800px; top: -200px; right: -200px; }
  .bg-circle-2 { width: 600px; height: 600px; bottom: 200px; left: -200px; }

  /* Header */
  .header {
    padding: 80px 120px 50px;
    text-align: center;
    position: relative;
    z-index: 1;
  }
  .header-org {
    font-size: 28px;
    font-weight: 600;
    color: #0077C0;
    letter-spacing: 4px;
    text-transform: uppercase;
    margin-bottom: 20px;
  }
  .header h1 {
    font-size: 72px;
    font-weight: 800;
    color: #1a2332;
    line-height: 1.15;
    margin-bottom: 20px;
    letter-spacing: -1px;
  }
  .header h1 span {
    color: #0077C0;
  }
  .header .subtitle {
    font-size: 30px;
    color: #5a6a7a;
    font-weight: 400;
    max-width: 1600px;
    margin: 0 auto;
    line-height: 1.5;
  }

  /* Key metrics banner */
  .metrics-banner {
    display: flex;
    justify-content: center;
    gap: 40px;
    padding: 40px 100px;
    margin: 10px 120px 30px;
    background: linear-gradient(135deg, #0077C0 0%, #005A94 100%);
    border-radius: 24px;
    position: relative;
    z-index: 1;
    box-shadow: 0 8px 32px rgba(0,119,192,0.25);
  }
  .metric-item {
    text-align: center;
    flex: 1;
    padding: 10px 20px;
    border-right: 1px solid rgba(255,255,255,0.2);
  }
  .metric-item:last-child { border-right: none; }
  .metric-value {
    font-size: 56px;
    font-weight: 800;
    color: #ffffff;
    line-height: 1.1;
  }
  .metric-value.highlight {
    font-size: 64px;
    color: #FFD55A;
  }
  .metric-label {
    font-size: 22px;
    color: rgba(255,255,255,0.85);
    margin-top: 8px;
    font-weight: 500;
    line-height: 1.3;
  }

  /* Infographic container */
  .infographic-section {
    flex: 1;
    padding: 10px 100px 20px;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    position: relative;
    z-index: 1;
  }
  #container {
    width: 100%;
    height: 100%;
  }

  /* Footer */
  .footer {
    padding: 30px 120px 50px;
    text-align: center;
    position: relative;
    z-index: 1;
    border-top: 2px solid #e8eef4;
    margin: 0 120px;
  }
  .footer-text {
    font-size: 22px;
    color: #8a95a5;
    line-height: 1.6;
  }
  .footer-source {
    font-size: 20px;
    color: #a0aab5;
    margin-top: 8px;
  }
</style>
</head>
<body>
<div class="poster">
  <div class="bg-circle bg-circle-1"></div>
  <div class="bg-circle bg-circle-2"></div>

  <div class="header">
    <div class="header-org">World Health Organization — Emergency Response Framework</div>
    <h1>COVID-19 <span>Emergency Response</span><br>From Detection to Recovery</h1>
    <div class="subtitle">A structured, five-phase process backed by unprecedented global coordination — guiding 194 Member States from initial surveillance through long-term recovery.</div>
  </div>

  <div class="metrics-banner">
    <div class="metric-item">
      <div class="metric-value highlight">194</div>
      <div class="metric-label">WHO Member States<br>Coordinated</div>
    </div>
    <div class="metric-item">
      <div class="metric-value highlight">~1.9B</div>
      <div class="metric-label">COVAX Vaccine Doses<br>Delivered by Mid-2023</div>
    </div>
    <div class="metric-item">
      <div class="metric-value">200+</div>
      <div class="metric-label">Technical Guidance<br>Documents Issued</div>
    </div>
    <div class="metric-item">
      <div class="metric-value">6</div>
      <div class="metric-label">WHO Regions<br>Covered</div>
    </div>
    <div class="metric-item">
      <div class="metric-value">146</div>
      <div class="metric-label">Countries Receiving<br>COVAX Doses</div>
    </div>
  </div>

  <div class="infographic-section">
    <div id="container"></div>
  </div>

  <div class="footer">
    <div class="footer-text">This process flow represents a coordinated global health architecture designed to save lives and build resilience against future pandemics.</div>
    <div class="footer-source">Sources: WHO Emergency Response Framework · COVAX Facility Reports · WHO Weekly Epidemiological Records</div>
  </div>
</div>

<script src="/app/vendor/infographic.min.js"></script>
<script>
const syntax = `infographic sequence-snake-steps-compact-card
data
  title Five-Phase Response Process
  desc Structured WHO-guided progression from initial detection through long-term recovery
  sequences
    - label Phase 1: Surveillance & Early Detection
      desc National laboratories report unusual respiratory illness clusters via the IHR framework. WHO issued its first Disease Outbreak News on 5 January 2020, days after initial reports from Wuhan.
      icon mingcute/search-line
    - label Phase 2: Risk Assessment & Alert
      desc Rapid risk assessments evaluate spread likelihood, illness severity, and health system capacity. WHO declared COVID-19 a PHEIC on 30 January 2020.
      icon mingcute/alert-line
    - label Phase 3: Response Operations & Clinical Management
      desc WHO mobilizes technical teams for infection prevention, clinical protocols, health workforce training, supply chain logistics, and the Solidarity Trial research programme.
      icon mingcute/hospital-line
    - label Phase 4: Public Health & Social Measures
      desc Community-level interventions — PCR and rapid antigen testing, contact tracing, quarantine, and vaccination. COVAX delivered ~1.9 billion doses to 146 countries by mid-2023.
      icon mingcute/shield-line
    - label Phase 5: Recovery & Health System Resilience
      desc Restoring routine health services, strengthening preparedness through updated national action plans, addressing long COVID, and conducting after-action reviews.
      icon mingcute/refresh-line
  order asc
theme
  palette #0077C0 #00A5D9 #F0AB00 #2E8B8B #5B9BD5`;

const infographic = new AntVInfographic.Infographic({
  container: '#container',
  width: '100%',
  height: '100%',
});

infographic.render(syntax);

document.fonts?.ready.then(() => {
  infographic.render(syntax);
}).catch((error) => console.error('Error waiting for fonts to load:', error));
</script>
</body>
</html>
